 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Joining like-colored diagonal markers; other marks are preserved as fixed points.
    points = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color not in (4, 8):
                points.setdefault(color, []).append((r, c))
    for color, pts in points.items():
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2-r1, c2-c1
                if dr and abs(dr) == abs(dc):
                    sr = 1 if dr > 0 else -1
                    sc = 1 if dc > 0 else -1
                    for k in range(1, abs(dr)):
                        r, c = r1 + k*sr, c1 + k*sc
                        if grid[r][c] == 4 or grid[r][c] == 8:
                            out[r][c] = color
    # A 6 marker sets a full down-right diagonal beam through itself.
    h, w = len(grid), len(grid[0])
    for r0, row in enumerate(grid):
        for c0, color in enumerate(row):
            if color == 6:
                # Extend this slope down-right and up-left as far as possible.
                r, c = r0, c0
                while r > 0 and c > 0:
                    r -= 1; c -= 1
                while r < h and c < w:
                    if grid[r][c] in (4, 8):
                        out[r][c] = 6
                    r += 1; c += 1
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
