 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Connect diagonally aligned 1 markers, preserving any other marked cells.
    beams = set()
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            length = abs(dr)
            for step in range(1, length):
                r, c = r1 + step * sr, c1 + step * sc
                if grid[r][c] == background:
                    out[r][c] = 1
            # A 6 located on the 1-1 segment projects a perpendicular diagonal.
            for r6, c6 in sixes:
                d = r6 - r1
                if (0 <= d * sr <= length
                        and (c6 - c1) * sc == d * sr
                        and r6 - r1 == d):
                    beams.add((r6, c6, sr == sc))

    # The projected line is perpendicular to the 1 connector: a positive-slope
    # connector yields negative slope, and vice versa.
    for r0, c0, connector_positive_slope in beams:
        directions = ((-1, 1), (1, -1)) if connector_positive_slope else ((-1, -1), (1, 1))
        for sr, sc in directions:
            r, c = r0 + sr, c0 + sc
            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] == background:
                    out[r][c] = 6
                r += sr
                c += sc
    return out

